function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const INTEREST_LABELS: Record<string, string> = {
  subscription: "Подписка (2 пачки в месяц)",
  "one-time": "Разовый заказ",
  question: "Вопрос",
};

function leadMessage(data: {
  name: string;
  phone: string;
  interest: string;
  comment: string;
  utm_source: string;
  utm_campaign: string;
  utm_content: string;
  page_url: string;
}): string {
  const lines = [
    "🫘 <b>Новая заявка «Кварта»</b>",
    `Имя: ${escapeHtml(data.name)}`,
    `Телефон: ${escapeHtml(data.phone)}`,
    `Интерес: ${escapeHtml(INTEREST_LABELS[data.interest] ?? data.interest)}`,
  ];
  if (data.comment) lines.push(`Комментарий: ${escapeHtml(data.comment)}`);
  const src = [data.utm_source, data.utm_campaign, data.utm_content].filter(Boolean).join(" / ");
  lines.push(`Источник: ${src ? escapeHtml(src) : "прямой заход"}`);
  if (data.page_url) lines.push(`Страница: ${escapeHtml(data.page_url)}`);
  return lines.join("\n");
}

async function notifyTelegram(env: Env, text: string): Promise<void> {
  const token = env.TELEGRAM_BOT_TOKEN;
  const chatId = env.TELEGRAM_CHAT_ID;
  if (!token || !chatId) return;
  try {
    const res = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        chat_id: chatId,
        text,
        parse_mode: "HTML",
        disable_web_page_preview: true,
      }),
    });
    if (!res.ok) console.error("telegram notify status", res.status, await res.text());
  } catch (err) {
    console.error("telegram notify failed", err);
  }
}
